DO $$ DECLARE missing text[]:=ARRAY[]::text[];remaining bigint;jobs bigint:=0;BEGIN IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='lead_commercial' AND column_name='awaiting_response_since') THEN missing:=array_append(missing,'awaiting_response_since');END IF;IF NOT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_schema='public' AND table_name='lead_commercial' AND column_name='response_deadline_at') THEN missing:=array_append(missing,'response_deadline_at');END IF;IF to_regclass('public.lead_commercial_response_deadline_r60_idx') IS NULL THEN missing:=array_append(missing,'deadline_index');END IF;IF (SELECT count(*) FROM pg_trigger WHERE NOT tgisinternal AND tgname IN('r60_materialize_commercial_response_deadline_trg','r60_refresh_response_deadline_from_sent_trg','r60_refresh_response_deadline_from_message_trg'))<>3 THEN missing:=array_append(missing,'three_triggers');END IF;IF to_regprocedure('public.service_expire_awaiting_response_leads_r60()') IS NULL THEN missing:=array_append(missing,'expiry_function');END IF;SELECT count(*) INTO remaining FROM public.lead_commercial WHERE commercial_stage='aguardando_resposta' AND response_deadline_at IS NULL;IF remaining<>0 THEN missing:=array_append(missing,'backfill_remaining='||remaining);END IF;IF to_regclass('cron.job') IS NOT NULL THEN SELECT count(*) INTO jobs FROM cron.job WHERE jobname='vinsansi-commercial-awaiting-response-timeout-r60';IF jobs<>1 THEN missing:=array_append(missing,'cron_jobs='||jobs);END IF;END IF;IF cardinality(missing)>0 THEN RAISE EXCEPTION 'r60_commercial_deadline_verify_failed:%',array_to_string(missing,',');END IF;END $$;
